/// <summary>
/// clicked
/// </summary>
public void clicked()
{
    boolean recordFound = false;
    FormButtonControl formButtonControl = any2Object(this) as FormButtonControl;
    FormDataSource formDatasource = formButtonControl.formRun().dataSource(tableStr(LedgerJournalTrans));
    LedgerJournalTrans ledgerJournalTransCur = formDatasource.cursor();
    LedgerJournalTrans ledgerJournalTrans;
    DimensionAttributeValueCombination dimensionAttributeValueCombination;

    next clicked();
    ttsbegin;
    while select forupdate AVAEndDate, Voucher, JournalNum, Txt, LedgerDimension  from ledgerJournalTrans where ledgerJournalTrans.JournalNum == ledgerJournalTransCur.JournalNum
    {
        if(ledgerJournalTrans.AVAEndDate <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()) && ledgerJournalTrans.AVAEndDate != dateNull())
        {
            recordFound = true;
            select firstonly * from dimensionAttributeValueCombination where dimensionAttributeValueCombination.RecId == ledgerJournalTrans.LedgerDimension;
            Info(strFmt("@NDX:NXAEndDateDelInfo", ledgerJournalTrans.Voucher, dimensionAttributeValueCombination.DisplayValue, ledgerJournalTrans.Txt));
            ledgerJournalTrans.delete();
        }
    }
    if(recordFound == false)
    {
        info("@NDX:NXAEndDateCheckSuccess");
    }
    formDatasource.research(true);
    formDatasource.refresh();
    formDatasource.reread();
    ttscommit;
}
